/**
 * OFFLINE A/B ASSEMBLER — Stage D actual v1.12.6 and v1.12.7 output.
 * No new DSP, EQ, reverb, sample synthesis, normalization, or external audio.
 * Inputs must be the authentic, identical-gain WAVs generated by
 * scripts/render_piano_d_ab_wav.mjs.
 *
 * node scripts/assemble_stage_d_bass_interleaved.mjs \
 *   artifacts/stage-d-comparacao-ab artifacts/stage-d-interleaved-bass
 */
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join} from 'node:path';
const RATE=48000,CHANNELS=2,BITS=24,FRAME_BYTES=6,BLOCK=128;
const clipFrames=Math.round(1.98*RATE);
const preFrames=Math.round(.12*RATE);
const interGapFrames=Math.round(.27*RATE),groupGapFrames=Math.round(.60*RATE);
const fadedFrames=Math.round(.010*RATE);
const entries=[
  ['C2','pp',.45],['C2','mf',2.68],['C2','ff',4.91],
  ['C3','pp',7.14],['C3','mf',9.37],['C3','ff',11.60],
  ['C4','mf',13.84],['A1','mf',16.10],['Chord C2/G2/C3/E3/G3','mf',18.48]
];
function wavPCM(path){
  const wav=readFileSync(path);
  if(wav.toString('ascii',0,4)!=='RIFF'||wav.toString('ascii',8,12)!=='WAVE'||
     wav.toString('ascii',12,16)!=='fmt '||wav.toString('ascii',36,40)!=='data'||
     wav.readUInt16LE(20)!==1||wav.readUInt16LE(22)!==CHANNELS||
     wav.readUInt32LE(24)!==RATE||wav.readUInt16LE(34)!==BITS||
     wav.readUInt16LE(32)!==FRAME_BYTES||wav.readUInt32LE(16)!==16||
     wav.readUInt32LE(40)!==wav.length-44)
    throw new Error('unexpected PCM24 stereo 48kHz WAV header: '+path);
  return wav.subarray(44);
}
function wavHeader(payloadBytes){
  const h=Buffer.alloc(44);
  h.write('RIFF',0,'ascii');h.writeUInt32LE(36+payloadBytes,4);
  h.write('WAVE',8,'ascii');h.write('fmt ',12,'ascii');
  h.writeUInt32LE(16,16);h.writeUInt16LE(1,20);h.writeUInt16LE(CHANNELS,22);
  h.writeUInt32LE(RATE,24);h.writeUInt32LE(RATE*FRAME_BYTES,28);
  h.writeUInt16LE(FRAME_BYTES,32);h.writeUInt16LE(BITS,34);
  h.write('data',36,'ascii');h.writeUInt32LE(payloadBytes,40);
  return h;
}
function copyWithEdgeFades(pcm,startFrame){
  const b=Buffer.from(pcm.subarray(startFrame*FRAME_BYTES,(startFrame+clipFrames)*FRAME_BYTES));
  if(b.length!==clipFrames*FRAME_BYTES)throw new RangeError('WAV source too short');
  // Edge fades only: original hammer onset occurs ~120 ms inside the cut.
  for(let i=0;i<fadedFrames;i++){
    const factor=i/fadedFrames;
    for(const frame of [i,clipFrames-1-i]){
      for(let c=0;c<CHANNELS;c++){
        const offset=frame*FRAME_BYTES+c*3;
        const original=b.readIntLE(offset,3);
        b.writeIntLE(Math.round(original*factor),offset,3);
      }
    }
  }
  return b;
}
function rmsAt(pcm,startSeconds,duration){
  const frame=Math.round(startSeconds*RATE),count=Math.round(duration*RATE);
  let total=0;
  for(let i=frame;i<frame+count;i++){
    const offset=i*FRAME_BYTES;
    if(offset+FRAME_BYTES>pcm.length)throw Error('RMS outside audio');
    const m=(pcm.readIntLE(offset,3)+pcm.readIntLE(offset+3,3))/(2*8388608);
    total+=m*m;
  }
  return Math.sqrt(total/count);
}
const dbr=(x,y)=>Number((20*Math.log10(Math.max(1e-12,y)/Math.max(1e-12,x))).toFixed(2));
const sourceDir=process.argv[2]||'artifacts/stage-d-comparacao-ab';
const targetDir=process.argv[3]||'artifacts/stage-d-interleaved-bass';
const meta=JSON.parse(readFileSync(join(sourceDir,'metadata.json'),'utf8'));
if(!meta.exactSameScheduledEvents||meta.individualNormalization||
   meta.quality!=='studio'||meta.sampleRate!==RATE||
   meta.channels!==CHANNELS||meta.pcmBits!==BITS)
  throw new Error('source render must use identical events, shared gain and Studio PCM24');
const a=wavPCM(join(sourceDir,'01_Stage_D_v1.12.6_original_48k_stereo_24bit.wav'));
const b=wavPCM(join(sourceDir,'02_Stage_D_v1.12.7_martelo_48k_stereo_24bit.wav'));
if(a.length!==b.length)throw Error('version WAV sizes mismatch');
const chunks=[],program=[],energy=[];
const pairGap=Buffer.alloc(interGapFrames*FRAME_BYTES);
const groupGap=Buffer.alloc(groupGapFrames*FRAME_BYTES);
let outputFrames=0;
for(let index=0;index<entries.length;index++){
  const [note,dynamic,time]=entries[index];
  const onsetFrame=Math.round(time*RATE/BLOCK)*BLOCK;
  const startFrame=onsetFrame-preFrames;
  if(startFrame<0)throw Error('insufficient pre-roll');
  program.push({
    note,dynamic,sourceNoteOnSeconds:time,
    historicalStartsSeconds:Number((outputFrames/RATE).toFixed(3)),
    experimentalStartsSeconds:Number(((outputFrames+clipFrames+interGapFrames)/RATE).toFixed(3))
  });
  chunks.push(copyWithEdgeFades(a,startFrame),pairGap,copyWithEdgeFades(b,startFrame));
  outputFrames+=clipFrames*2+interGapFrames;
  if(index<entries.length-1){chunks.push(groupGap);outputFrames+=groupGapFrames;}
  const onset=onsetFrame/RATE;
  energy.push({note,dynamic,
    deltaD122_first12ms:dbr(rmsAt(a,onset,.012),rmsAt(b,onset,.012)),
    deltaDb_body100to220ms:dbr(rmsAt(a,onset+.1,.12),rmsAt(b,onset+.1,.12)),
    deltaDb_tail900to1180ms:dbr(rmsAt(a,onset+.9,.28),rmsAt(b,onset+.9,.28))
  });
}
const pcm=Buffer.concat(chunks);
if(pcm.length!==outputFrames*FRAME_BYTES)throw Error('audio frame count mismatch');
mkdirSync(targetDir,{recursive:true});
const filename='Stage_D_v126_v127_graves_AB_intercalado_48k_stereo_24bit.wav';
writeFileSync(join(targetDir,filename),Buffer.concat([wavHeader(pcm.length),pcm]));
const report={
  schema:'stage-d-v126-v127-graves-interleaved-ab-v1',
  source:'scripts/render_piano_d_ab_wav.mjs, official Stage DSP',
  versions:['v1.12.6 archived Stage D','v1.12.7 experimental Stage D'],
  sampleRate:RATE,channels:CHANNELS,bits:BITS,quality:'studio',
  noExternalSamples:true,fx:'disabled',sameOutputGain:true,individualNormalization:false,
  processing:'interleaved original note cuts; 10ms edge fades, no DSP modifications',
  durationSeconds:Number((outputFrames/RATE).toFixed(3)),clipSeconds:clipFrames/RATE,
  groupSilenceSeconds:groupGapFrames/RATE,
  betweenVariantsSilenceSeconds:interGapFrames/RATE,
  sourceWaveformsOriginal:true,sourceVersionsUnchanged:true,
  caveat:'dB differences measure relative variant energy, not piano realism; previous-note tails are included equally in both version renders; C4 signal can differ due to previous bass tails.',
  program,relativeEnergyDb:energy
};
writeFileSync(join(targetDir,'stage-d-bass-interleaved-report.json'),JSON.stringify(report,null,2)+'\n');
console.log('STAGE_D_BASS_AB '+JSON.stringify({
  file:filename,durationSeconds:report.durationSeconds,
  relativeEnergyDb:report.relativeEnergyDb
}));
